#!/usr/bin/env python3
"""Generates src/Chassis.Core/Catalog/parts.json, the built-in parts list.

Edit the tables below, then run:  python3 tools/catalog/build_parts.py
Prices are typical US street prices (approximate). Benchmark figures (multi/single = Cinebench R23,
game = relative gaming index with Ryzen 7 9800X3D = 100, raster/rt = relative 4K index with RTX 4090 = 100)
are rounded averages from published reviews; Chassis uses them only to estimate performance.
"""
import json, pathlib

OUT = pathlib.Path(__file__).resolve().parents[2] / "src/Chassis.Core/Catalog/parts.json"
parts = []

def add(pid, cat, brand, name, price, color, key, spec):
    parts.append({"id": pid, "cat": cat, "brand": brand, "name": name, "price": price, "color": color, key: spec})

